#!/usr/bin/env bash
# Regenerate the committed C header for the plugin ABI, or check that the
# committed header still matches the crate.
#
# `repr(C)` Rust in `crates/plugin-contract/src/abi` is the source of truth
# (D2). The header is generated by `cbindgen` and committed, and CI fails when
# regeneration produces a diff. It is the artifact a non-Rust implementer
# compiles against, so it is never edited by hand: a compile error in it is
# fixed in the Rust source.
#
# Usage, from the repository root:
#   bash scripts/regenerate-abi-header.sh           # regenerate in place
#   bash scripts/regenerate-abi-header.sh --check   # fail when the header drifts
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
crate_dir="$repo_root/crates/plugin-contract"
header="$crate_dir/include/metis_plugin_abi.h"

# The header goes to stdout, so the --check path can compare it without ever
# touching the committed file.
generate() {
  cbindgen --config "$crate_dir/cbindgen.toml" "$crate_dir"
}

if [ "${1:-}" = "--check" ]; then
  scratch="$(mktemp)"
  trap 'rm -f "$scratch"' EXIT
  generate > "$scratch"
  if ! diff -u "$header" "$scratch"; then
    echo "drift check: $header does not match crates/plugin-contract/src/abi" >&2
    echo "drift check: run 'bash scripts/regenerate-abi-header.sh' and commit the result" >&2
    exit 1
  fi
  echo "drift check: the ABI header matches the crate"
  exit 0
fi

mkdir -p "$(dirname "$header")"
generate > "$header"
echo "regenerated $header"
